package com.qrpublic.apartment.adapter.user.request;

import jakarta.validation.constraints.NotBlank;
import lombok.Data;

/**
 * Create (or reset) an account whose password is generated by the user
 * service and never returned: the real password arrives later through the
 * single-use setup link. Used for yoga buyer provisioning and admin-triggered
 * password reset.
 */
@Data
public class GenerateAccountRequest {
    @NotBlank
    private String userName;
    private String fullName;
    /** SELLER | BUYER; defaults to BUYER when blank */
    private String role;
}
